export function isTailscaleAddress(address) {
  const m = /^100\.(\d{1,3})\.\d{1,3}\.\d{1,3}$/.exec(String(address ?? ''));
  if (m === null) return false;
  const second = Number(m[1]);
  return second >= 64 && second <= 127;
